class CanonicalWorldModel:
    version = "wm-latent-v1"

    def init_state(self, observation):
        return {"value": observation["value"], "double": False}

    def transition(self, state, action):
        if action["kind"] == "toggle":
            return {"value": state["value"], "double": not state["double"]}
        factor = 2 if state["double"] else 1
        return {
            "value": state["value"] + action["delta"] * factor,
            "double": state["double"],
        }

    def observe(self, state):
        return {"value": state["value"]}

